CREATE TABLE tipo_consorcio (id BIGINT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE usuario (id BIGINT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, tipo VARCHAR(40) NOT NULL, ativo BOOLEAN NOT NULL);
CREATE TABLE perfil (id BIGINT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE consorcio (id BIGINT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255) NOT NULL UNIQUE, tipo_id BIGINT NOT NULL, ativo BOOLEAN NOT NULL, CONSTRAINT fk_consorcio_tipo FOREIGN KEY (tipo_id) REFERENCES tipo_consorcio(id));
CREATE TABLE grupo (id BIGINT AUTO_INCREMENT PRIMARY KEY, numero VARCHAR(255) NOT NULL UNIQUE, consorcio_id BIGINT NOT NULL, quantidade_cotas INT, valor_parcela DECIMAL(15,2), CONSTRAINT fk_grupo_consorcio FOREIGN KEY (consorcio_id) REFERENCES consorcio(id));
CREATE TABLE cota (id BIGINT AUTO_INCREMENT PRIMARY KEY, numero VARCHAR(255) NOT NULL, grupo_id BIGINT NOT NULL, valor_credito DECIMAL(15,2) NOT NULL, ativa BOOLEAN NOT NULL, CONSTRAINT fk_cota_grupo FOREIGN KEY (grupo_id) REFERENCES grupo(id));
CREATE TABLE usuario_perfil (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT NOT NULL, perfil_id BIGINT NOT NULL, criado_em DATETIME(6), CONSTRAINT fk_up_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id), CONSTRAINT fk_up_perfil FOREIGN KEY (perfil_id) REFERENCES perfil(id));
CREATE TABLE participacao_cota (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT NOT NULL, cota_id BIGINT NOT NULL, inicio DATE NOT NULL, fim DATE, ativa BOOLEAN NOT NULL, CONSTRAINT fk_pc_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id), CONSTRAINT fk_pc_cota FOREIGN KEY (cota_id) REFERENCES cota(id));
CREATE TABLE assembleia (id BIGINT AUTO_INCREMENT PRIMARY KEY, grupo_id BIGINT NOT NULL, data DATE NOT NULL, observacao VARCHAR(255), CONSTRAINT fk_assembleia_grupo FOREIGN KEY (grupo_id) REFERENCES grupo(id));
CREATE TABLE lance (id BIGINT AUTO_INCREMENT PRIMARY KEY, cota_id BIGINT NOT NULL, assembleia_id BIGINT NOT NULL, tipo VARCHAR(40) NOT NULL, valor DECIMAL(15,2) NOT NULL, CONSTRAINT fk_lance_cota FOREIGN KEY (cota_id) REFERENCES cota(id), CONSTRAINT fk_lance_assembleia FOREIGN KEY (assembleia_id) REFERENCES assembleia(id));
CREATE TABLE contemplacao (id BIGINT AUTO_INCREMENT PRIMARY KEY, cota_id BIGINT NOT NULL, assembleia_id BIGINT NOT NULL, lance_id BIGINT, data DATE NOT NULL, tipo VARCHAR(40) NOT NULL, valor DECIMAL(15,2) NOT NULL, CONSTRAINT fk_cont_cota FOREIGN KEY (cota_id) REFERENCES cota(id), CONSTRAINT fk_cont_assembleia FOREIGN KEY (assembleia_id) REFERENCES assembleia(id), CONSTRAINT fk_cont_lance FOREIGN KEY (lance_id) REFERENCES lance(id));
CREATE TABLE processo_contemplacao (id BIGINT AUTO_INCREMENT PRIMARY KEY, contemplacao_id BIGINT NOT NULL UNIQUE, responsavel_id BIGINT, status VARCHAR(50) NOT NULL, criado_em DATETIME(6), atualizado_em DATETIME(6), CONSTRAINT fk_processo_cont FOREIGN KEY (contemplacao_id) REFERENCES contemplacao(id), CONSTRAINT fk_processo_resp FOREIGN KEY (responsavel_id) REFERENCES usuario(id));
CREATE TABLE historico_processo (id BIGINT AUTO_INCREMENT PRIMARY KEY, processo_id BIGINT NOT NULL, status_anterior VARCHAR(50), novo_status VARCHAR(50) NOT NULL, usuario_id BIGINT NOT NULL, data DATETIME(6) NOT NULL, observacao VARCHAR(255), CONSTRAINT fk_hp_processo FOREIGN KEY (processo_id) REFERENCES processo_contemplacao(id), CONSTRAINT fk_hp_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id));
CREATE TABLE baixa (id BIGINT AUTO_INCREMENT PRIMARY KEY, processo_id BIGINT NOT NULL UNIQUE, usuario_id BIGINT NOT NULL, data DATETIME(6) NOT NULL, observacao VARCHAR(255), CONSTRAINT fk_baixa_processo FOREIGN KEY (processo_id) REFERENCES processo_contemplacao(id), CONSTRAINT fk_baixa_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id));
CREATE TABLE comunicacao (id BIGINT AUTO_INCREMENT PRIMARY KEY, processo_id BIGINT NOT NULL, canal VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, responsavel_id BIGINT NOT NULL, CONSTRAINT fk_com_processo FOREIGN KEY (processo_id) REFERENCES processo_contemplacao(id), CONSTRAINT fk_com_resp FOREIGN KEY (responsavel_id) REFERENCES usuario(id));
CREATE TABLE historico_comunicacao (id BIGINT AUTO_INCREMENT PRIMARY KEY, comunicacao_id BIGINT NOT NULL, data DATETIME(6) NOT NULL, canal VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, usuario_id BIGINT NOT NULL, resposta VARCHAR(255), observacao VARCHAR(255), CONSTRAINT fk_hc_com FOREIGN KEY (comunicacao_id) REFERENCES comunicacao(id), CONSTRAINT fk_hc_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id));
CREATE TABLE documento (id BIGINT AUTO_INCREMENT PRIMARY KEY, processo_id BIGINT NOT NULL, tipo VARCHAR(50) NOT NULL, status VARCHAR(40) NOT NULL, nome_arquivo VARCHAR(255), observacao VARCHAR(255), CONSTRAINT fk_doc_processo FOREIGN KEY (processo_id) REFERENCES processo_contemplacao(id));
CREATE TABLE parcela (id BIGINT AUTO_INCREMENT PRIMARY KEY, cota_id BIGINT NOT NULL, numero INT NOT NULL, vencimento DATE NOT NULL, valor DECIMAL(15,2) NOT NULL, status VARCHAR(40) NOT NULL, CONSTRAINT fk_parcela_cota FOREIGN KEY (cota_id) REFERENCES cota(id));
CREATE TABLE pagamento (id BIGINT AUTO_INCREMENT PRIMARY KEY, parcela_id BIGINT NOT NULL, data DATE NOT NULL, valor DECIMAL(15,2) NOT NULL, comprovante VARCHAR(255), CONSTRAINT fk_pagamento_parcela FOREIGN KEY (parcela_id) REFERENCES parcela(id));
CREATE TABLE notificacao (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT NOT NULL, processo_id BIGINT, titulo VARCHAR(255) NOT NULL, mensagem VARCHAR(1000) NOT NULL, lida BOOLEAN NOT NULL, criada_em DATETIME(6), CONSTRAINT fk_not_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id), CONSTRAINT fk_not_processo FOREIGN KEY (processo_id) REFERENCES processo_contemplacao(id));
CREATE TABLE auditoria (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT, acao VARCHAR(255) NOT NULL, entidade VARCHAR(255) NOT NULL, registro_id BIGINT, data DATETIME(6) NOT NULL, detalhes VARCHAR(2000), CONSTRAINT fk_aud_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id));